<?php
declare(strict_types=1);
require_once __DIR__.'/speaking-content.php';require_once __DIR__.'/game.php';
function eqs_words(string $s): array {$numbers=["zero","one","two","three","four","five","six","seven","eight","nine","ten","eleven","twelve","thirteen","fourteen","fifteen","sixteen","seventeen","eighteen","nineteen","twenty"];preg_match_all("/[a-z]+(?:'[a-z]+)?|[0-9]+/",game_normalize($s),$m);return array_slice(array_map(fn($word)=>ctype_digit($word)&&isset($numbers[(int)$word])?$numbers[(int)$word]:$word,$m[0]),0,180);}
function eqs_compare(string $sample,string $heard): array {
 $a=eqs_words($sample);$b=eqs_words($heard);$n=count($a);$m=count($b);$d=array_fill(0,$n+1,array_fill(0,$m+1,0));for($i=$n-1;$i>=0;$i--)for($j=$m-1;$j>=0;$j--)$d[$i][$j]=$a[$i]===$b[$j]?1+$d[$i+1][$j+1]:max($d[$i+1][$j],$d[$i][$j+1]);$aligned=[];$extra=[];$i=0;$j=0;
 while($i<$n||$j<$m){if($i<$n&&$j<$m&&$a[$i]===$b[$j]){$aligned[]=['word'=>$a[$i],'status'=>'matched'];$i++;$j++;}elseif($i<$n&&($j===$m||$d[$i+1][$j]>=$d[$i][$j+1])){$aligned[]=['word'=>$a[$i],'status'=>'missing'];$i++;}else{$extra[]=$b[$j];$j++;}}
 $match=(int)round(($d[0][0]??0)/max(1,$n,$m)*100);return ['content_match'=>$match,'expected'=>$aligned,'extra'=>$extra,'missing'=>array_column(array_filter($aligned,fn($x)=>$x['status']==='missing'),'word'),'feedback'=>$match>=85?'Văn bản nhận diện khá sát câu mẫu. Nghe lại nhịp câu và tự đối chiếu bản ghi.':($match>=40?'Hãy chia câu thành các cụm ngắn và đọc lại những từ được đánh dấu.':'Thử nghe chậm, kiểm tra micro và đọc từng cụm. Nhận diện sai cũng có thể do tiếng ồn hoặc dịch vụ trình duyệt.'),'disclaimer'=>'Đây là độ khớp nội dung văn bản, không phải điểm phát âm hay điểm IELTS.'];
}
function eqs_save(PDO $p,int $uid,array $in): never {
 $id=hub_text($in,'session',40);$transcript=hub_text($in,'transcript',2000);$file=$in['file_id']??null;$consent=($in['record_consent']??false)===true;if($file!==null){if(!is_int($file)||!$consent)fail(422,'Cần đồng ý rõ ràng trước khi lưu bản ghi âm.');$f=hub_owned_file($p,$uid,$file);/* libmagic may report audio-only MediaRecorder WebM as video/webm. Both labels describe the same permitted WebM container. */if(!str_starts_with($f['mime'],'audio/')&&$f['mime']!=='video/webm')fail(422,'Cần tệp âm thanh/WebM của chính bạn.');}
 limit_attempts($p,'speaking-result:'.$uid,60,3600);$p->beginTransaction();try{
  $lock=$p->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?' FOR UPDATE':'';$r=hub_q($p,'SELECT * FROM eqs_practice_sessions WHERE id=? AND user_id=?'.$lock,[$id,$uid])->fetch();if(!$r){$p->rollBack();fail(404,'Không tìm thấy lượt luyện của bạn.');}$old=hub_q($p,'SELECT result_json FROM eqs_attempts WHERE session_id=?',[$id])->fetchColumn();if($old){$p->commit();reply(200,['ok'=>true,'result'=>json_decode($old,true),'duplicate'=>true]);}if(time()-(int)$r['started_at']>3600){$p->rollBack();fail(409,'Lượt luyện đã hết hạn sau một giờ. Hãy mở lượt mới.');}$task=json_decode($r['payload'],true,32,JSON_THROW_ON_ERROR);$result=eqs_compare($task['sample'],$transcript);
  try{hub_q($p,'INSERT INTO eq_progress(user_id,state) VALUES (?,?)',[$uid,json_encode(game_initial())]);}catch(PDOException $e){if((string)$e->getCode()!=='23000')throw $e;}$pr=json_decode(hub_q($p,'SELECT state FROM eq_progress WHERE user_id=?'.$lock,[$uid])->fetchColumn(),true,512,JSON_THROW_ON_ERROR);$day=date('Y-m-d');$used=(int)hub_q($p,'SELECT COALESCE(SUM(xp),0) FROM eqs_rewards WHERE user_id=? AND day=?',[$uid,$day])->fetchColumn();$already=hub_q($p,'SELECT 1 FROM eqs_rewards WHERE user_id=? AND day=? AND task_key=?',[$uid,$day,$r['task_key']])->fetchColumn();$xp=!$already&&$used<30&&$result['content_match']>=40&&time()-(int)$r['started_at']>=3?min(5,30-$used):0;
  if($xp)hub_q($p,'INSERT INTO eqs_rewards(user_id,day,task_key,xp) VALUES (?,?,?,?)',[$uid,$day,$r['task_key'],$xp]);$pr['xp']+=$xp;if(!in_array($day,$pr['days'],true))$pr['days'][]=$day;$pr['history']=array_slice([['title'=>'Luyện nói · '.$task['title'],'score'=>$result['content_match'],'total'=>100,'date'=>date('c')],...$pr['history']],0,100);$pr['daily']??=[];$pr['daily'][$day]=($pr['daily'][$day]??0)+1;hub_q($p,'UPDATE eq_progress SET state=? WHERE user_id=?',[json_encode($pr,JSON_UNESCAPED_UNICODE),$uid]);
  hub_q($p,'INSERT INTO eqx_speaking(user_id,sample,transcript,created_at) VALUES (?,?,?,?)',[$uid,$task['sample'],$transcript,time()]);$legacy=(int)$p->lastInsertId();$result+=['xp'=>$xp,'sample'=>$task['sample'],'transcript'=>$transcript,'record_saved'=>$file!==null,'daily_xp_remaining'=>max(0,30-$used-$xp)];hub_q($p,'INSERT INTO eqs_attempts(user_id,session_id,legacy_id,mode,level,topic,content_match,result_json,record_file_id,record_consent,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)',[$uid,$id,$legacy,$task['mode'],$task['level'],$task['topic'],$result['content_match'],json_encode($result,JSON_UNESCAPED_UNICODE),$file,$file!==null?1:0,time()]);$p->commit();reply(200,['ok'=>true,'result'=>$result]);
 }catch(Throwable $e){if($p->inTransaction())$p->rollBack();throw $e;}
}
function eq_speaking(PDO $p,int $uid,array $config,string $op,array $in): never {
 if($op==='speaking_catalog'){$level=hub_profile($p,$uid)['level'];$tasks=eqs_catalog();$pool=array_values(array_filter($tasks,fn($t)=>$t['mode']==='scenario'&&$t['level']===$level));$daily=$pool[hexdec(substr(hash('sha256',date('Y-m-d').':'.$uid),0,6))%count($pool)];reply(200,['ok'=>true,'tasks'=>$tasks,'topics'=>array_map(fn($t)=>['title'=>$t[0],'role'=>$t[1]],eqs_topics()),'daily'=>$daily,'level'=>$level,'policy'=>['daily_xp_cap'=>30,'xp_per_new_task'=>5,'pronunciation_scoring'=>false]]);}
 if($op==='speaking_begin'){limit_attempts($p,'speaking-start:'.$uid,80,3600);$task=eqs_task(hub_text($in,'key',100));if(!$task)fail(404,'Bài luyện không tồn tại.');$id=bin2hex(random_bytes(16));hub_q($p,'INSERT INTO eqs_practice_sessions(id,user_id,task_key,payload,started_at) VALUES (?,?,?,?,?)',[$id,$uid,$task['key'],json_encode($task,JSON_UNESCAPED_UNICODE),time()]);reply(200,['ok'=>true,'session'=>$id,'task'=>$task]);}
 if($op==='speaking_result')eqs_save($p,$uid,$in);
 if($op==='speaking_history_full'){$before=$in['before']??PHP_INT_MAX;if(!is_int($before)||$before<1)fail(422,'Trang chưa hợp lệ.');$rows=hub_q($p,'SELECT s.id,s.sample,s.transcript,s.created_at,a.mode,a.level,a.content_match,a.record_file_id,a.result_json FROM eqx_speaking s LEFT JOIN eqs_attempts a ON a.legacy_id=s.id AND a.user_id=s.user_id WHERE s.user_id=? AND s.id<? ORDER BY s.id DESC LIMIT 31',[$uid,$before])->fetchAll();$more=count($rows)>30;$rows=array_slice($rows,0,30);foreach($rows as &$row){$row['result']=$row['result_json']?json_decode($row['result_json'],true):null;unset($row['result_json']);}unset($row);reply(200,['ok'=>true,'history'=>$rows,'has_more'=>$more,'next_before'=>$rows?(int)end($rows)['id']:null]);}
 if($op==='speaking_conversations')reply(200,['ok'=>true,'conversations'=>hub_q($p,'SELECT * FROM eqs_conversations WHERE user_id=? ORDER BY created_at DESC LIMIT 50',[$uid])->fetchAll()]);
 if($op==='speaking_conversation_create'){$topic=hub_text($in,'topic',60);$level=hub_text($in,'level',2);if(!isset(eqs_topics()[$topic])||!in_array($level,['A1','A2','B1','B2','C1','C2'],true))fail(422,'Chủ đề hoặc trình độ chưa hợp lệ.');limit_attempts($p,'speaking-conversations:'.$uid,20,3600);$id=bin2hex(random_bytes(16));hub_q($p,'INSERT INTO eqs_conversations(id,user_id,topic,level,created_at) VALUES (?,?,?,?,?)',[$id,$uid,$topic,$level,time()]);reply(200,['ok'=>true,'conversation'=>['id'=>$id,'topic'=>$topic,'level'=>$level],'turns'=>[]]);}
 if(in_array($op,['speaking_conversation','speaking_turn'],true)){
  $id=hub_text($in,'conversation',40);$c=hub_q($p,'SELECT * FROM eqs_conversations WHERE id=? AND user_id=?',[$id,$uid])->fetch();if(!$c)fail(404,'Không tìm thấy hội thoại của bạn.');if($op==='speaking_conversation')reply(200,['ok'=>true,'conversation'=>$c,'turns'=>hub_q($p,'SELECT id,question,answer,status,source,created_at FROM eqs_turns WHERE conversation_id=? ORDER BY id',[$id])->fetchAll()]);
  $key=hub_text($in,'key',64);if(!preg_match('/^[a-zA-Z0-9-]{16,64}$/D',$key))fail(422,'Mã gửi chưa hợp lệ.');$question=hub_text($in,'question',2000);limit_attempts($p,'speaking-ai:'.$uid,8,60);$p->beginTransaction();try{
   hub_q($p,'SELECT id FROM eqs_conversations WHERE id=?'.($p->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?' FOR UPDATE':''),[$id]);$old=hub_q($p,'SELECT * FROM eqs_turns WHERE conversation_id=? AND client_key=?',[$id,$key])->fetch();if($old){$p->commit();if($old['status']==='complete')reply(200,['ok'=>true,'turn'=>$old,'duplicate'=>true]);fail(409,'Lượt gửi này đang xử lý hoặc đã lỗi. Kiểm tra lịch sử trước khi gửi lại.');}
   if((int)hub_q($p,'SELECT COUNT(*) FROM eqs_turns WHERE conversation_id=?',[$id])->fetchColumn()>=100){$p->rollBack();fail(422,'Hội thoại đã đủ 100 lượt. Hãy tạo cuộc trò chuyện mới.');}if(hub_q($p,"SELECT 1 FROM eqs_turns WHERE conversation_id=? AND status='pending' AND created_at>?",[$id,time()-90])->fetchColumn()){$p->rollBack();fail(409,'Đang có một câu trả lời được xử lý.');}
   hub_q($p,'INSERT INTO eqs_turns(conversation_id,client_key,question,created_at) VALUES (?,?,?,?)',[$id,$key,$question,time()]);$tid=(int)$p->lastInsertId();$p->commit();
  }catch(Throwable $e){if($p->inTransaction())$p->rollBack();throw $e;}
  $history=array_reverse(hub_q($p,"SELECT question,answer FROM eqs_turns WHERE conversation_id=? AND status='complete' ORDER BY id DESC LIMIT 6",[$id])->fetchAll());require_once __DIR__.'/hub-ai.php';$topic=eqs_topics()[$c['topic']];$ctx=['topic'=>$topic[0],'role'=>$topic[1],'level'=>$c['level'],'recent_dialogue'=>$history,'instructions'=>'Act as the named conversation partner. Reply naturally in English with one follow-up question. Then provide a brief Vietnamese explanation under Vocabulary and Grammar. Do not claim to hear audio or assess pronunciation; you only receive a transcript. For IELTS scenarios this is unofficial language practice, never award a band score.'];
  try{$res=hub_ai($p,$uid,$config,'speaking_roleplay',$question,$ctx);}catch(Throwable $e){hub_q($p,"UPDATE eqs_turns SET status='failed',source='error' WHERE id=?",[$tid]);throw $e;}
  if(($res['source']??'')!=='gemini'){hub_q($p,"UPDATE eqs_turns SET status='failed',source='unavailable' WHERE id=?",[$tid]);reply(503,['ok'=>false,'code'=>'AI_UNAVAILABLE','message'=>$res['reason']??'Gemini chưa sẵn sàng. Luyện nói theo mẫu vẫn sử dụng được.']);}
  hub_q($p,"UPDATE eqs_turns SET answer=?,source='gemini',status='complete' WHERE id=?",[$res['answer'],$tid]);hub_q($p,'INSERT INTO eqx_speaking(user_id,sample,transcript,created_at) VALUES (?,?,?,?)',[$uid,'Hội thoại · '.$topic[0],$question,time()]);reply(200,['ok'=>true,'turn'=>['id'=>$tid,'question'=>$question,'answer'=>$res['answer'],'source'=>'gemini','status'=>'complete','created_at'=>time()]]);
 }
 fail(404,'Không tìm thấy chức năng Luyện nói.');
}
